export const ACERO_LOCATIONS_MAP: Record<string, AceroLocationMeta> = {};
export const ACERO_LOCATIONS_BY_CODE: Record<string, AceroLocationMeta> = {};

for (const row of RAW_ACERO_DATA) {
  const [clave, planta, pasillo, estante, nivel, posicion, ubicacion, shelfCode] = row;
  const meta: AceroLocationMeta = {
    clave,
    planta,
    pasillo,
    estante,
    nivel,
    posicion,
    ubicacion,
    shelfCode
  };
  ACERO_LOCATIONS_MAP[`${clave}_${shelfCode}_${nivel}`] = meta;
  ACERO_LOCATIONS_MAP[`${clave}_${shelfCode}`] = meta;
  ACERO_LOCATIONS_MAP[`${clave}_${nivel}`] = meta;
  ACERO_LOCATIONS_MAP[ubicacion] = meta;
  if (!ACERO_LOCATIONS_BY_CODE[clave]) {
    ACERO_LOCATIONS_BY_CODE[clave] = meta;
  }
}

export function findAceroLocation(code: string, shelfCode?: string, section?: string): AceroLocationMeta | null {
  if (!code) return null;
  const c = code.trim().toUpperCase();
  const sh = (shelfCode || '').trim().toUpperCase();
  const sec = (section || '').trim().toUpperCase();

  if (ACERO_LOCATIONS_MAP[c]) {
    return ACERO_LOCATIONS_MAP[c];
  }
  if (sh && sec && ACERO_LOCATIONS_MAP[`${c}_${sh}_${sec}`]) {
    return ACERO_LOCATIONS_MAP[`${c}_${sh}_${sec}`];
  }
  if (sh && ACERO_LOCATIONS_MAP[`${c}_${sh}`]) {
    return ACERO_LOCATIONS_MAP[`${c}_${sh}`];
  }
  if (sec && ACERO_LOCATIONS_MAP[`${c}_${sec}`]) {
    return ACERO_LOCATIONS_MAP[`${c}_${sec}`];
  }
  if (ACERO_LOCATIONS_BY_CODE[c]) {
    return ACERO_LOCATIONS_BY_CODE[c];
  }
  return null;
}
